    <p>Zawadi, aged 22, plans to start a juice processing business. She has KSh 300 000 in savings, two friends willing to invest KSh 200 000 each, and a dairy co-operative nearby that might supply milk for smoothies. She is unsure whether to start alone, form a partnership, register a company or join a co-operative.</p>
